-- Step 4: verify what was actually written, or roll the whole thing back
DO $$
DECLARE v_periods INT; v_records INT; v_gross NUMERIC; v_net NUMERIC;
BEGIN
  SELECT count(*) INTO v_periods FROM payroll_periods WHERE month = 7 AND year = 2026;
  SELECT count(*), COALESCE(round(sum(r.total_gross)::numeric, 2), 0),
         COALESCE(round(sum(r.net_salary)::numeric, 2), 0)
    INTO v_records, v_gross, v_net
    FROM payroll_records r JOIN payroll_periods p ON p.id = r.period_id
   WHERE p.month = 7 AND p.year = 2026;
  IF v_periods <> 23 THEN
    RAISE EXCEPTION 'period count is %, expected 23', v_periods;
  END IF;
  IF v_records <> 2072 THEN
    RAISE EXCEPTION 'record count is %, expected 2072', v_records;
  END IF;
  IF v_gross <> 11744203.07 THEN
    RAISE EXCEPTION 'gross total is %, expected 11744203.07', v_gross;
  END IF;
  IF v_net <> 11570851.66 THEN
    RAISE EXCEPTION 'net total is %, expected 11570851.66', v_net;
  END IF;
  RAISE NOTICE 'يوليو 2026: % periods, % records, gross %, net %',
    v_periods, v_records, v_gross, v_net;
END $$;

COMMIT;
